import{_ as t,o as a,c as r,ai as i}from"./chunks/framework.lvpqbiZd.js";const p=JSON.parse('{"title":"Asumi client teams","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-31-asumi-client-teams-design.md","filePath":"superpowers/specs/2026-08-31-asumi-client-teams-design.md"}'),s={name:"superpowers/specs/2026-08-31-asumi-client-teams-design.md"};function n(o,e,d,c,l,m){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="asumi-client-teams" tabindex="-1">Asumi client teams <a class="header-anchor" href="#asumi-client-teams" aria-label="Permalink to “Asumi client teams”">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h2><p>Represent the three existing managed customer sites as separate Press teams on <code>asumi.ir</code>, while keeping the Administrator account as the only member and manager for now.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Create exactly three enabled, free teams:</p><table tabindex="0"><thead><tr><th>Team title</th><th>Customer site</th></tr></thead><tbody><tr><td>Dehati</td><td>dehati.ir</td></tr><tr><td>Denroom</td><td>denroom.ir</td></tr><tr><td>Veederakht</td><td>veederakht.ir</td></tr></tbody></table><p>Each team will have <code>Administrator</code> as its owner and sole team member. No customer user, billing information, server, bench, or site record will be created or changed in this step.</p><h2 id="safety-and-verification" tabindex="-1">Safety and verification <a class="header-anchor" href="#safety-and-verification" aria-label="Permalink to “Safety and verification”">​</a></h2><p>Creation is idempotent: an existing team with the same title is retained rather than duplicated. After creation, verify that exactly the three target teams exist, are enabled, and have only <code>Administrator</code> as a member.</p><h2 id="follow-up" tabindex="-1">Follow-up <a class="header-anchor" href="#follow-up" aria-label="Permalink to “Follow-up”">​</a></h2><p>The existing Frappe sites will be imported and assigned to their respective teams only after the current server and bench have been formally registered in Press. That separate step must not fabricate site records.</p>',11)])])}const b=t(s,[["render",n]]);export{p as __pageData,b as default};
